import{_ as t,H as a,f as o,i as s}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"en/guide/how-it-works.md"}'),d={name:"guide/how-it-works.md"};function i(n,e,c,l,r,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><p>At session start, a hook injects the <code>praxis:using-praxis</code> skill. On every message, the agent:</p><ol><li><strong>Classifies scope and topology</strong> inline using the triage table — no extra skill call needed.</li><li><strong>Announces</strong> the scope (and <code>topology=multi-module</code> if multi-repo) and loads required skills in parallel.</li><li><strong>Follows</strong> the loaded skills literally, respecting <code>&lt;gate&gt;</code> markers.</li></ol><h2 id="triage-announcement" tabindex="-1">Triage Announcement <a class="header-anchor" href="#triage-announcement" aria-label="Permalink to &quot;Triage Announcement&quot;">​</a></h2><p>Every response opens with a scope classification line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>praxis: scope=&lt;x&gt;, loading=&lt;skills&gt;                         # single-module (default)</span></span>
<span class="line"><span>praxis: scope=&lt;x&gt;, topology=multi-module, loading=&lt;skills&gt;  # multi-module</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scope</th><th>Signal</th><th>Skills loaded</th></tr></thead><tbody><tr><td>vague</td><td>problem space undefined — can&#39;t say what to build</td><td><code>design</code></td></tr><tr><td>trivial</td><td>typo, rename, docs-only, ≤1 line, pure Q</td><td>none</td></tr><tr><td>small</td><td>one function, single file, ≤50 LOC</td><td><code>tdd</code></td></tr><tr><td>standard</td><td>feature or source-code change</td><td><code>design</code>, <code>plan</code>, <code>tdd</code>, <code>review</code></td></tr><tr><td>complex</td><td>new system, ≥5 tasks, parallel edits</td><td><code>design</code>, <code>plan</code>, <code>worktree</code>, <code>subagents</code>, <code>review</code>, <code>ship</code></td></tr><tr><td>debug</td><td>broken, regression, failing test</td><td><code>debug</code></td></tr><tr><td>onboard</td><td>existing project, no tech-spec</td><td><code>onboard</code></td></tr></tbody></table><h2 id="core-lifecycle-gates" tabindex="-1">Core Lifecycle Gates <a class="header-anchor" href="#core-lifecycle-gates" aria-label="Permalink to &quot;Core Lifecycle Gates&quot;">​</a></h2><ol><li><strong>Spec Review Gate (<code>design</code>)</strong>: After drafting a spec, Praxis inspects trigger conditions and dispatches parallel reviewers (<code>spec-compliance</code>, <code>state-machine</code>, <code>cross-rule</code>, <code>cross-module</code>, <code>safety</code>, <code>implementability</code>). The coordinator synthesizes findings critically before plan handoff.</li><li><strong>3D Quality Gate (<code>tdd</code> / <code>review</code>)</strong>: Implementation cycles are evaluated against mechanical checks, convention adherence, design cohesion/coupling, and documentation coverage.</li><li><strong>Model Tier Dispatch (<code>subagents</code>)</strong>: Fan-out tasks designate a ROLE charter (<code>implementer</code>, <code>spec-reviewer</code>, <code>quality-reviewer</code>) and a capability tier (<code>fast</code>, <code>balanced</code>, <code>strongest</code>).</li><li><strong>Living Documentation Sync (<code>ship</code> / <code>archive</code>)</strong>: Staging specs merge into living docs (<code>docs/tech-spec.md</code> or <code>docs/specs/*.md</code>), CHANGELOG is updated, and staging files are cleaned up.</li></ol><h2 id="example-flows" tabindex="-1">Example flows <a class="header-anchor" href="#example-flows" aria-label="Permalink to &quot;Example flows&quot;">​</a></h2><h3 id="tiny-fix" tabindex="-1">Tiny fix <a class="header-anchor" href="#tiny-fix" aria-label="Permalink to &quot;Tiny fix&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You:   fix the typo &quot;teh&quot; in README</span></span>
<span class="line"><span>Agent: scope=trivial → edit → done</span></span></code></pre></div><h3 id="standard-feature" tabindex="-1">Standard feature <a class="header-anchor" href="#standard-feature" aria-label="Permalink to &quot;Standard feature&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You:   add OAuth login with GitHub</span></span>
<span class="line"><span>Agent: scope=standard → design (spec + spec review gate) → plan → tdd (quality check) → review → ship</span></span></code></pre></div><h3 id="multi-module-change" tabindex="-1">Multi-module change <a class="header-anchor" href="#multi-module-change" aria-label="Permalink to &quot;Multi-module change&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You:   add a shared checkout flow across api and web repos</span></span>
<span class="line"><span>Agent: scope=complex, topology=multi-module → design (coordinator spec) → plan → subagents per repo → ship</span></span></code></pre></div>`,16)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
